outputs.output:
{
  "title": "Does the green checkout button sell more?",
  "setting": "Week 2 at Pinecrest Gear",
  "mission": "Decide whether to **launch the new green checkout button** to all shoppers or keep testing.",
  "deadline": "Launch decision with {{product}} by Friday at 2:00 p.m.",
  "panels": [
    {
      "title": "A/B Test · Day 1 Results",
      "metrics": [
        {
          "label": "Blue button (A)",
          "value": "4.0%",
          "note": "8 purchases / 200 visitors"
        },
        {
          "label": "Green button (B)",
          "value": "6.5%",
          "note": "13 purchases / 200 visitors"
        },
        {
          "label": "Difference",
          "value": "+2.5%",
          "note": "5 extra purchases"
        }
      ],
      "note": "Live for 6 hours · 400 total visitors split evenly"
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Senior data analyst",
      "expertise": "Cares about clean experiments and avoiding false alarms.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Understands shoppers and wants to hit this month's sales goal fast.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Runs quick math and checks how often random luck creates a gap.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a bad call",
      "start": 50,
      "goodWhen": "low"
    },
    {
      "id": "patience",
      "label": "{{product}}'s patience",
      "start": 75,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Tell a real difference from chance",
      "practice": "Look at two small groups in daily life, like two lines at a grocery store, and list one reason a gap between them could just be luck."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Before comparing two options, write down how many tries you will watch before you look at the score."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Rewrite one sentence with a math term like 'p-value' or 'statistical significance' into plain words a friend would use."
    }
  ],
  "startNodeId": "day1-check",
  "nodes": [
    {
      "id": "day1-check",
      "messages": [
        {
          "from": "product",
          "text": "Look at the dashboard! The green button is up at 6.5% and the old blue one is at 4.0%. Let's switch everyone to green before the evening rush."
        },
        {
          "from": "data",
          "text": "Hold on, {{product}}. That is only 8 purchases versus 13 purchases. In **hypothesis testing**, we start by asking if a gap this size could happen just by random luck."
        }
      ],
      "prompt": "What do you do with the Day 1 numbers?",
      "choices": [
        {
          "id": "ask-ai-chance",
          "text": "Ask {{ai}} how often a 5-purchase gap happens by pure luck with 200 visitors each.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "If both buttons actually sell at the same rate, random luck alone creates a gap this big or bigger about 26% of the time (that is a **p-value** of 0.26). That is roughly like flipping two heads in a row."
            },
            {
              "from": "data",
              "text": "Exactly. Usually we wait until luck has less than a 5% chance of explaining the gap before we call it real."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You checked whether a 5-purchase gap out of 200 visitors per group could just be everyday luck before acting on it.",
              "example": null
            }
          ],
          "next": "explain-wait"
        },
        {
          "id": "launch-now",
          "text": "Agree with {{product}} and launch the green button now so we don't miss evening sales.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Love the speed! I'll ask engineering to push the green button to 100% of shoppers right after lunch."
            },
            {
              "from": "data",
              "text": "Wait—if we ship on just 21 total purchases, we have no idea if green is actually better. Let's at least check how many visitors a solid test needs before they flip the switch."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 30
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "With only 200 visitors per button, 5 extra sales happens by random luck about 1 time in 4. Check with {{ai}} or {{data}} before calling a winner.",
              "example": "Let's ask {{ai}} if a 5-sale gap on 200 visitors could just be a lucky streak."
            }
          ],
          "next": "sample-check"
        },
        {
          "id": "wait-one-hour",
          "text": "Compromise by waiting for 100 more visitors per button before making the call.",
          "quality": "fair",
          "replies": [
            {
              "from": "data",
              "text": "Waiting is the right instinct, though 300 visitors per button is still pretty small for a 4% purchase rate."
            },
            {
              "from": "ai",
              "text": "At 200 visitors per group, a 5-sale gap happens by luck 26% of the time. Adding 100 visitors helps a little, but won't clear the fog."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 5
            },
            {
              "meter": "patience",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You paused instead of calling a winner on 21 total sales, giving the test more room to settle.",
              "example": null
            }
          ],
          "next": "explain-wait"
        }
      ]
    },
    {
      "id": "explain-wait",
      "messages": [
        {
          "from": "product",
          "text": "Okay, I see you two staring at numbers, but what does that mean in plain English? Why shouldn't I take a 6.5% conversion rate right now?"
        }
      ],
      "prompt": "How do you explain the Day 1 result to {{product}}?",
      "choices": [
        {
          "id": "plain-coin-flip",
          "text": "Tell {{product}} that with only 200 shoppers each, a 5-sale lead happens by pure luck about 1 time in 4, like flipping two heads in a row.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Oh, 1 in 4? I definitely wouldn't bet our checkout page on two coin flips. How long do we actually need to run it?"
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You translated the 26% chance into '1 time in 4' and a coin flip, making the risk clear without jargon.",
              "example": null
            }
          ],
          "next": "sample-check"
        },
        {
          "id": "jargon-pvalue",
          "text": "Tell {{product}} that the p-value is 0.26, which exceeds our 0.05 alpha threshold, so we cannot reject the null hypothesis yet.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "You lost me at 'null hypothesis.' Look, just tell me how many shoppers we need so we aren't guessing."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 0
            },
            {
              "meter": "patience",
              "change": -25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Terms like 'p-value' and 'null hypothesis' are shortcuts for analysts, not clear answers for partners.",
              "example": "With so few visitors, a 5-sale gap happens by luck about 1 time in 4, so we can't trust it yet."
            }
          ],
          "next": "sample-check"
        },
        {
          "id": "vague-small",
          "text": "Tell {{product}} that 400 total visitors is too small a sample size and data rules say we have to wait longer.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "I hate waiting just because of 'rules,' but fine. How many visitors do the rules say we need?"
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -5
            },
            {
              "meter": "patience",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Saying a sample is 'too small' feels like a rule unless you show how easily luck can fake the lead.",
              "example": "With 200 visitors per button, just 5 lucky shoppers create that whole gap—about a 1 in 4 chance."
            }
          ],
          "next": "sample-check"
        }
      ]
    },
    {
      "id": "sample-check",
      "messages": [
        {
          "from": "data",
          "text": "Let's set a clear **sample size**—the number of visitors we need before we judge the test—so we don't just peek every hour and stop when green looks ahead."
        },
        {
          "from": "ai",
          "text": "Our store gets about 1,000 visitors a day. To reliably spot a real jump from 4.0% to 5.2% (30% more sales) without getting fooled by luck, we need **3,500 visitors per button**—about 7 days in total."
        }
      ],
      "prompt": "Which test plan do you set with the team?",
      "choices": [
        {
          "id": "full-3500",
          "text": "Run the test to 3,500 visitors per button (7 days total) and hold off on calling a winner until then.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Seven days feels long, but if that's what it takes to know for sure, I'll move our launch check-in to next week."
            },
            {
              "from": "data",
              "text": "Great call. That gives weekday and weekend shoppers a fair look at both buttons."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": {
            "label": "6 days later · 3,500 visitors per button",
            "panel": {
              "title": "A/B Test · Day 7 Final Results",
              "metrics": [
                {
                  "label": "Blue button (A)",
                  "value": "4.2%",
                  "note": "147 purchases / 3,500 visitors"
                },
                {
                  "label": "Green button (B)",
                  "value": "4.1%",
                  "note": "144 purchases / 3,500 visitors"
                },
                {
                  "label": "Difference",
                  "value": "-0.1%",
                  "note": "3 fewer purchases on Green"
                }
              ],
              "note": "Full sample reached · Chance of luck: 84% (no real difference)"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You committed to the 3,500-visitor sample size needed to tell a real sales lift from random noise.",
              "example": null
            }
          ],
          "next": "final-call-full"
        },
        {
          "id": "peek-daily",
          "text": "Check the numbers every morning and stop the test as soon as one button leads for two days straight.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "That sounds faster! Let's watch it tomorrow and Friday."
            },
            {
              "from": "data",
              "text": "Careful—stopping as soon as one side looks ahead is like ending a coin-flip game the moment you're winning. You'll catch a lucky streak, not a real improvement."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 25
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": {
            "label": "2 days later · 1,200 visitors per button",
            "panel": {
              "title": "A/B Test · Day 3 Snapshot",
              "metrics": [
                {
                  "label": "Blue button (A)",
                  "value": "4.2%",
                  "note": "50 purchases / 1,200 visitors"
                },
                {
                  "label": "Green button (B)",
                  "value": "5.0%",
                  "note": "60 purchases / 1,200 visitors"
                },
                {
                  "label": "Difference",
                  "value": "+0.8%",
                  "note": "10 extra purchases"
                }
              ],
              "note": "Stopped early at 2,400 total visitors · Chance of luck: 33%"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Stopping whenever a button pulls ahead makes it much easier to get tricked by a random streak. Pick the sample size up front and wait for it.",
              "example": "Let's wait until both buttons reach 3,500 visitors before we decide."
            }
          ],
          "next": "final-call-early"
        },
        {
          "id": "stop-friday",
          "text": "Stop on Friday afternoon at 1,200 visitors per button so {{product}} has an answer before the weekend.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Thanks for keeping Friday's deadline in mind."
            },
            {
              "from": "data",
              "text": "1,200 per button is better than 200, though only a huge jump would be clear by then."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 10
            },
            {
              "meter": "patience",
              "change": 5
            }
          ],
          "timeJump": {
            "label": "2 days later · 1,200 visitors per button",
            "panel": {
              "title": "A/B Test · Day 3 Snapshot",
              "metrics": [
                {
                  "label": "Blue button (A)",
                  "value": "4.2%",
                  "note": "50 purchases / 1,200 visitors"
                },
                {
                  "label": "Green button (B)",
                  "value": "5.0%",
                  "note": "60 purchases / 1,200 visitors"
                },
                {
                  "label": "Difference",
                  "value": "+0.8%",
                  "note": "10 extra purchases"
                }
              ],
              "note": "2,400 total visitors · Chance of luck: 33%"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "1,200 visitors per group is about a third of what {{ai}} calculated, leaving a 1-in-3 chance that a 10-sale gap is just luck.",
              "example": "Let's give it the full 3,500 visitors per button so we don't mistake a small streak for a real lift."
            }
          ],
          "next": "final-call-early"
        }
      ]
    },
    {
      "id": "final-call-full",
      "messages": [
        {
          "from": "data",
          "text": "Look at Day 7: Blue is at 4.2% (147 purchases) and Green is at 4.1% (144 purchases). That early Day 1 spike completely vanished once enough shoppers came through."
        },
        {
          "from": "product",
          "text": "Whoa. I really thought Green was a huge winner on Day 1. So what's the official call for the team?"
        }
      ],
      "prompt": "What do you recommend to {{product}} after the full 7-day test?",
      "choices": [
        {
          "id": "keep-blue-clear",
          "text": "Keep the blue button and explain that over 7,000 shoppers, both colors sold at basically the same rate (4.2% vs. 4.1%).",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "Makes total sense. Glad we didn't waste engineering time switching colors when shoppers don't actually care. Let's test a faster checkout form next!"
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -15
            },
            {
              "meter": "patience",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You gave a clear recommendation backed by the full 7,000-visitor numbers in plain language.",
              "example": null
            },
            {
              "skill": "chance",
              "kind": "good",
              "text": "You recognized that a 3-purchase difference across 7,000 visitors means the two buttons perform the same.",
              "example": null
            }
          ],
          "next": "ending-solid"
        },
        {
          "id": "claim-blue-beats-green",
          "text": "Declare that the blue button beats green by 0.1% and warn that green hurts sales.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "Careful—a 3-purchase gap out of 7,000 visitors is pure noise too! Blue isn't beating green; they're tied."
            },
            {
              "from": "product",
              "text": "Got it, so they're basically tied. We'll stick with blue and move on."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "Just as Green's early lead was luck, Blue's 3-sale lead over 7,000 visitors happens by luck 84% of the time. Treat it as a tie.",
              "example": "Both buttons converted right around 4.1% to 4.2%, so color didn't change shopper behavior."
            }
          ],
          "next": "ending-solid"
        }
      ]
    },
    {
      "id": "final-call-early",
      "messages": [
        {
          "from": "product",
          "text": "It's Friday! Green is at 5.0% (60 sales) and Blue is at 4.2% (50 sales). That's 10 more sales! Can we launch Green now?"
        },
        {
          "from": "ai",
          "text": "Heads up: with 1,200 visitors per button, a 10-sale gap still happens by random luck **33% of the time** (1 time in 3). We are still 2,300 visitors short per button."
        }
      ],
      "prompt": "What is your call on Friday afternoon?",
      "choices": [
        {
          "id": "extend-to-full",
          "text": "Tell {{product}} there is still a 1-in-3 chance the 10-sale lead is luck, and keep the test running to 3,500 visitors each.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "A 1-in-3 chance of being fooled is still too high. Okay, let's let it run through Tuesday so we hit 3,500 each."
            },
            {
              "from": "data",
              "text": "Good recovery. Waiting four more days saves us from shipping a false alarm."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -25
            },
            {
              "meter": "patience",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "Even with 10 extra sales on the board, you checked the 1-in-3 chance of luck and held off on calling a winner.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "good",
              "text": "Stating '1-in-3 chance of luck' helped {{product}} see why 1,200 visitors wasn't enough yet.",
              "example": null
            }
          ],
          "next": "ending-rescued"
        },
        {
          "id": "ship-green-friday",
          "text": "Call Green the winner at 5.0% versus 4.2% and roll it out to all shoppers before the weekend.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Awesome! Launching Green to 100% of traffic right now."
            },
            {
              "from": "data",
              "text": "I'll log the launch, though with a 1-in-3 chance that this lead was just luck, we shouldn't be surprised if next month's sales stay flat at 4.2%."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 30
            },
            {
              "meter": "patience",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "A 10-purchase gap across 2,400 visitors happens by random luck 1 time in 3. Waiting for the full 3,500 per group prevents chasing false leads.",
              "example": "A 10-sale lead at this size still happens by luck 1 time in 3—let's finish the 3,500-visitor target first."
            }
          ],
          "next": "ending-false-alarm"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "ending-solid",
      "outcome": "After 3,500 visitors per button, Green (4.1%) and Blue (4.2%) finished in a dead heat. You saved the team from chasing a Day 1 lucky streak and moved on to testing a faster checkout form."
    },
    {
      "id": "ending-rescued",
      "outcome": "By holding out for the full 3,500 visitors per button, you watched Green's early lead fade to 4.1% versus Blue's 4.2%. The team kept the blue button and knew they could trust the numbers."
    },
    {
      "id": "ending-false-alarm",
      "outcome": "Green went live to everyone after 1,200 visitors per button, but over the next month purchases settled right back to 4.2%—the early 5.0% lead had just been a lucky streak."
    }
  ],
  "summary": [
    "In a small sample, a few lucky purchases can create a big percentage gap by pure chance.",
    "Choose your sample size before the test starts and wait until you reach it instead of stopping as soon as one option pulls ahead.",
    "When sharing test results, translate terms like p-value into everyday odds—such as a 1-in-4 chance that the gap is just luck."
  ]
}

{
  "title": "E se o mundo ao nosso redor funcionasse em pacotes quânticos?",
  "setting": "Sábado de manhã na padaria do bairro",
  "mission": "Descubra como fazer suas coisas funcionarem em uma manhã em que **tudo no bairro passou a agir como um quantum**.",
  "deadline": null,
  "panels": [
    {
      "title": "Manhã estranha no bairro",
      "metrics": [
        {
          "label": "Torneira de café",
          "value": "Só 50 ml por vez",
          "note": "Não sai no meio-termo"
        },
        {
          "label": "Luz na janela",
          "value": "Listras e pontos",
          "note": "Pisca na parede"
        }
      ],
      "note": "As regras do mundo atômico invadiram o tamanho humano"
    }
  ],
  "team": [
    {
      "id": "fisica",
      "role": "Vizinha física",
      "expertise": "Adora explicar os mistérios do universo tomando um pingado.",
      "ai": false
    },
    {
      "id": "padeiro",
      "role": "Dono da padaria",
      "expertise": "Quer atender a fila rápido e entender o que houve com suas máquinas.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "curiosidade",
      "label": "Descobertas do dia",
      "start": 50,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "pacotes",
      "name": "Energia em pacotes",
      "practice": "Olhe ao redor e encontre três coisas do dia a dia que só vêm em unidades inteiras, como degraus de uma escada ou moedas."
    },
    {
      "id": "dualidade",
      "name": "Onda e partícula",
      "practice": "Explique para alguém em uma frase como a luz pode se espalhar como onda na água e bater como gotinhas de chuva."
    }
  ],
  "startNodeId": "cafe",
  "nodes": [
    {
      "id": "cafe",
      "messages": [
        {
          "from": "padeiro",
          "text": "Gente, a térmica de café enlouqueceu! Tento tirar só um chorinho para esquentar sua xícara, mas ou não cai nada, ou cai um jato certinho de 50 ml."
        },
        {
          "from": "fisica",
          "text": "Que incrível! Parece que hoje o café está vindo em _quanta_, que são pacotes mínimos indivisíveis. Na natureza, a energia funciona exatamente assim!"
        }
      ],
      "prompt": "Você quer 100 ml de café na sua xícara. Como você tenta se servir nessa máquina?",
      "choices": [
        {
          "id": "abrir-devagar",
          "text": "Abro a torneira bem devagarzinho para tentar fazer o café escorrer em um fio contínuo até dar 100 ml.",
          "quality": "weak",
          "replies": [
